void display_error (UInt16 err_code, UInt8 display_count)
{	
  Display_Cmd display_cmd_new ;

  timeout_stop  (display_timeout) ;	

  display_cmd_new.id = DISPLAY_ERROR ;

  display_cmd_new.arg.cmd_error.err_code         = err_code      ;
  display_cmd_new.arg.cmd_error.display_count    = display_count ;

  display_pass_cmd (& display_cmd_new) ;
}

